import Database from 'better-sqlite3';
import { join } from 'path';

const dbPath = join(process.cwd(), 'db.sqlite');
export const db = new Database(dbPath);

// Enable foreign keys
db.pragma('foreign_keys = ON');

// Initialize database schema
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    role TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS content (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    body TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    userId INTEGER NOT NULL,
    expiresAt INTEGER NOT NULL,
    FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE
  );
`);

// Seed data if empty
const userCount = (db.prepare('SELECT COUNT(*) as count FROM users').get() as { count: number }).count;
if (userCount === 0) {
  const insertUser = db.prepare('INSERT INTO users (username, password, role) VALUES (?, ?, ?)');
  insertUser.run('admin', 'Admin#123', 'admin');
  insertUser.run('editor', 'Editor#123', 'editor');
  insertUser.run('viewer', 'Viewer#123', 'viewer');
}

const contentCount = (db.prepare('SELECT COUNT(*) as count FROM content').get() as { count: number }).count;
if (contentCount === 0) {
  const insertContent = db.prepare('INSERT INTO content (title, body) VALUES (?, ?)');
  insertContent.run('Getting Started', 'Welcome to the dashboard');
  insertContent.run('Company Roadmap', 'Plans for the next quarter');
}

export interface User {
  id: number;
  username: string;
  role: 'admin' | 'editor' | 'viewer';
}

export interface Session {
  id: string;
  userId: number;
  expiresAt: number;
}

export interface Content {
  id: number;
  title: string;
  body: string;
}

import crypto from 'crypto';
import { db, type User, type Session } from './db';

const SESSION_DURATION = 24 * 60 * 60 * 1000; // 24 hours in milliseconds

export function createSession(userId: number): string {
  const sessionId = crypto.randomUUID();
  const expiresAt = Date.now() + SESSION_DURATION;

  const insertSession = db.prepare('INSERT INTO sessions (id, userId, expiresAt) VALUES (?, ?, ?)');
  insertSession.run(sessionId, userId, expiresAt);

  return sessionId;
}

export function getSession(sessionId: string): { user: User; session: Session } | null {
  const session = db.prepare('SELECT * FROM sessions WHERE id = ?').get(sessionId) as Session | undefined;
  if (!session) {
    return null;
  }

  if (Date.now() > session.expiresAt) {
    db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId);
    return null;
  }

  const user = db.prepare('SELECT id, username, role FROM users WHERE id = ?').get(session.userId) as User | undefined;
  if (!user) {
    db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId);
    return null;
  }

  return { user, session };
}

export function deleteSession(sessionId: string): void {
  db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId);
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { getSession } from '../lib/session';

export const onRequest: RequestHandler = async (event) => {
  const sessionCookie = event.cookie.get('session');
  if (sessionCookie) {
    const sessionData = getSession(sessionCookie.value);
    if (sessionData) {
      event.sharedMap.set('user', sessionData.user);
      event.sharedMap.set('session', sessionData.session);
    }
  }
  await event.next();
};

